<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_report_reasons() { return array( 'spam' => __( 'Spam', 'social-discovery-core' ), 'harassment' => __( 'Harassment', 'social-discovery-core' ), 'hate' => __( 'Hate or abuse', 'social-discovery-core' ), 'impersonation' => __( 'Impersonation', 'social-discovery-core' ), 'privacy' => __( 'Privacy violation', 'social-discovery-core' ), 'inappropriate' => __( 'Inappropriate content', 'social-discovery-core' ), 'other' => __( 'Other', 'social-discovery-core' ) ); }
function sd_core_create_report( $data ) { global $wpdb; $t = sd_core_table_names(); $target_type = sanitize_key( $data['target_type'] ?? '' ); $target_id = absint( $data['target_id'] ?? 0 ); $reason = sanitize_key( $data['reason'] ?? '' ); $description = sanitize_textarea_field( $data['description'] ?? '' ); if ( ! in_array( $target_type, array( 'member', 'activity', 'comment', 'group', 'message' ), true ) || ! $target_id || ! array_key_exists( $reason, sd_core_report_reasons() ) ) { return new WP_Error( 'invalid_report', __( 'Please provide valid report details.', 'social-discovery-core' ), array( 'status' => 400 ) ); } if ( 'member' === $target_type && ! get_userdata( $target_id ) ) { return new WP_Error( 'invalid_target', __( 'That member is unavailable.', 'social-discovery-core' ), array( 'status' => 404 ) ); } if ( 'message' === $target_type && ( ! function_exists( 'sd_core_message_thread_allowed' ) || ! sd_core_message_thread_allowed( $target_id ) ) ) { return new WP_Error( 'private_target', __( 'You can only report a conversation you participate in.', 'social-discovery-core' ), array( 'status' => 403 ) ); } if ( 'activity' === $target_type && function_exists( 'sd_core_activity_visible' ) && ! sd_core_activity_visible( $target_id ) ) { return new WP_Error( 'invalid_target', __( 'That activity is unavailable.', 'social-discovery-core' ), array( 'status' => 404 ) ); } $exists = $wpdb->get_var( $wpdb->prepare( "SELECT id FROM {$t['reports']} WHERE reporter_id=%d AND target_type=%s AND target_id=%d AND status IN ('pending','under_review') LIMIT 1", get_current_user_id(), $target_type, $target_id ) ); if ( $exists ) { return new WP_Error( 'duplicate_report', __( 'You have already reported this item.', 'social-discovery-core' ), array( 'status' => 409 ) ); } $wpdb->insert( $t['reports'], array( 'reporter_id' => get_current_user_id(), 'target_type' => $target_type, 'target_id' => $target_id, 'reason' => $reason, 'description' => $description, 'status' => 'pending', 'created_at' => current_time( 'mysql', true ), 'updated_at' => current_time( 'mysql', true ) ), array( '%d', '%s', '%d', '%s', '%s', '%s', '%s', '%s' ) ); $id = $wpdb->insert_id; sd_core_audit( 'report_created', $target_type, $target_id, 'success', $reason, $id ); return $id ? $id : new WP_Error( 'report_failed', __( 'The report could not be submitted.', 'social-discovery-core' ), array( 'status' => 500 ) ); }
